defmodule Mix.Tasks.Protox.Benchmark.Corpus.Stats do
  @moduledoc false

  use Mix.Task

  alias Mix.Tasks.Protox.Benchmark.Run
  alias Protox.{Field, OneOf, Scalar}

  # Reports the value distributions of the benchmark corpus, bucketing every value that
  # actually reaches the wire by its declared protobuf type.
  #
  # This exists because the corpus was previously generated by the test suite's
  # property-testing generator, which made the benchmark spend most of its time on paths
  # real traffic does not take: 75% of encoded floats were NaN/Infinity, 45% of varints
  # were full 10-byte negatives, and 94% of strings were non-ASCII. Those are exactly the
  # numbers this task surfaces, so the corpus can be argued about with evidence.
  #
  # The captured google_message1 rows are the reference: real production bytes. The
  # generated rows should resemble them; the edge_* and *_edge rows should not, by design.

  @impl Mix.Task
  @spec run(any) :: any
  def run(_args) do
    payloads = Run.get_payloads("./benchmark/benchmark_payloads.bin")

    Mix.shell().info(
      String.pad_trailing("input", 26) <>
        "  populated  submsg  empty-rep  1B-varint  10B-varint  NaN/Inf  non-ASCII"
    )

    payloads
    |> Enum.sort_by(fn {_name, {_mod, samples}} -> total_size(samples) end)
    |> Enum.each(fn {name, {mod, samples}} ->
      Mix.shell().info(format_row(name, Enum.reduce(samples, %{}, fn {msg, _s, _b}, acc -> scan(mod, msg, acc) end)))
    end)

    Mix.shell().info("")

    Mix.shell().info(
      "note: presence is read from the decoded struct, which cannot represent a proto3 field " <>
        "explicitly written at its default. google_message1_proto3 therefore understates " <>
        "`populated`: its 228 captured bytes re-encode to 221. Everything else is generated " <>
        "from structs, so the struct is the authoritative view for those rows."
    )
  end

  defp format_row(name, acc) do
    get = fn key -> Map.get(acc, key, 0) end
    varints = Enum.map(1..10, &get.({:varint, &1}))

    String.pad_trailing(name, 26) <>
      pct(get.({:scalar, :set}), get.({:scalar, :set}) + get.({:scalar, :default}), 11) <>
      pct(get.({:msg, :set}), get.({:msg, :set}) + get.({:msg, :unset}), 8) <>
      pct(get.({:coll, :empty}), get.({:coll, :empty}) + get.({:coll, :filled}), 11) <>
      pct(Enum.at(varints, 0), Enum.sum(varints), 11) <>
      pct(Enum.at(varints, 9), Enum.sum(varints), 12) <>
      pct(get.({:float, :special}), get.({:float, :special}) + get.({:float, :normal}), 9) <>
      pct(get.({:string, :unicode}), get.({:string, :unicode}) + get.({:string, :ascii}), 11)
  end

  defp pct(_count, 0, width), do: String.pad_leading("-", width)
  defp pct(count, total, width), do: String.pad_leading("#{Float.round(100 * count / total, 1)}%", width)

  defp total_size(samples) do
    samples
    |> Stream.map(fn {_msg, size, _bytes} -> size end)
    |> Enum.sum()
  end

  defp scan(mod, msg, acc) do
    {oneofs, regular} =
      mod.schema().fields
      |> Map.values()
      |> Enum.split_with(&match?(%OneOf{}, &1.kind))

    regular
    |> Enum.reduce(acc, fn %Field{} = field, inner -> field(field, Map.fetch!(msg, field.name), inner) end)
    |> scan_oneofs(oneofs, msg)
  end

  # A oneof member is stored under its parent's key as {member_name, value}, so the members
  # have to be resolved through the parent rather than read field by field. Skipping them
  # would drop whatever the selected member holds, which is very much on the wire.
  defp scan_oneofs(acc, [], _msg), do: acc

  defp scan_oneofs(acc, oneofs, msg) do
    by_name = Map.new(oneofs, fn %Field{} = field -> {field.name, field} end)

    oneofs
    |> Enum.map(fn %Field{kind: %OneOf{parent: parent}} -> parent end)
    |> Enum.uniq()
    |> Enum.reduce(acc, fn parent, inner ->
      case Map.fetch!(msg, parent) do
        nil -> bump(inner, {:scalar, :default})
        {name, value} -> oneof(Map.fetch!(by_name, name), value, inner)
      end
    end)
  end

  defp oneof(%Field{type: {:message, sub}}, value, acc), do: scan(sub, value, bump(acc, {:msg, :set}))

  defp oneof(%Field{type: type}, value, acc),
    do:
      acc
      |> bump({:scalar, :set})
      |> value(type, value)

  defp field(%Field{kind: %Scalar{}, type: {:message, _sub}}, nil, acc), do: bump(acc, {:msg, :unset})

  defp field(%Field{kind: %Scalar{}, type: {:message, sub}}, value, acc) do
    scan(sub, value, bump(acc, {:msg, :set}))
  end

  defp field(%Field{kind: %Scalar{default_value: default}, type: type}, value, acc) do
    if value == default do
      bump(acc, {:scalar, :default})
    else
      acc
      |> bump({:scalar, :set})
      |> value(type, value)
    end
  end

  # Map keys are encoded alongside their values, so they count too.
  defp field(%Field{kind: :map, type: {key_type, {:message, sub}}}, value, acc) do
    Enum.reduce(value, collection(acc, map_size(value)), fn {key, entry}, inner ->
      scan(sub, entry, value(inner, key_type, key))
    end)
  end

  defp field(%Field{kind: :map, type: {key_type, value_type}}, value, acc) do
    Enum.reduce(value, collection(acc, map_size(value)), fn {key, entry}, inner ->
      inner
      |> value(key_type, key)
      |> value(value_type, entry)
    end)
  end

  defp field(%Field{kind: kind, type: {:message, sub}}, value, acc) when kind in [:packed, :unpacked] do
    Enum.reduce(value, collection(acc, length(value)), &scan(sub, &1, &2))
  end

  defp field(%Field{kind: kind, type: type}, value, acc) when kind in [:packed, :unpacked] do
    Enum.reduce(value, collection(acc, length(value)), &value(&2, type, &1))
  end

  defp field(_field, _value, acc), do: acc

  defp collection(acc, 0), do: bump(acc, {:coll, :empty})
  defp collection(acc, _length), do: bump(acc, {:coll, :filled})

  # sint32/sint64 zigzag before the varint, so a small negative stays cheap; int32/int64
  # sign-extend to 64 bits, so any negative costs the full ten bytes.
  defp value(acc, type, number) when type in [:sint32, :sint64] and is_integer(number) do
    bump(acc, {:varint, varint_bytes(zigzag(number))})
  end

  defp value(acc, type, number) when type in [:int32, :int64] and is_integer(number) do
    bump(acc, {:varint, signed_varint_bytes(number)})
  end

  defp value(acc, type, number) when type in [:uint32, :uint64] and is_integer(number) do
    bump(acc, {:varint, varint_bytes(number)})
  end

  # bool and enum are varints as well. Leaving them out understated the one-byte share and
  # inflated the ten-byte one, because a bool is always a single byte and so is almost every
  # enum constant. (fixed*/sfixed* are *not* varints and stay excluded.)
  defp value(acc, :bool, _flag), do: bump(acc, {:varint, 1})

  defp value(acc, {:enum, mod}, constant) do
    bump(acc, {:varint, signed_varint_bytes(enum_number(mod, constant))})
  end

  defp value(acc, type, number) when type in [:float, :double] do
    bump(acc, {:float, if(is_atom(number), do: :special, else: :normal)})
  end

  defp value(acc, :string, text) when is_binary(text) do
    bump(acc, {:string, if(String.length(text) == byte_size(text), do: :ascii, else: :unicode)})
  end

  defp value(acc, _type, _value), do: acc

  # An unknown enum value is kept as the raw integer; a known one is an atom.
  defp enum_number(_mod, number) when is_integer(number), do: number

  defp enum_number(mod, constant) do
    Enum.find_value(mod.constants(), 0, fn {number, name} -> if name == constant, do: number end)
  end

  defp zigzag(number) when number < 0, do: -2 * number - 1
  defp zigzag(number), do: 2 * number

  defp signed_varint_bytes(number) when number < 0, do: 10
  defp signed_varint_bytes(number), do: varint_bytes(number)

  defp varint_bytes(number), do: max(1, ceil(:math.log2(number + 1) / 7))

  defp bump(acc, key), do: Map.update(acc, key, 1, &(&1 + 1))
end
